<label class="auth-label block text-xs font-semibold">Kata sandi<div class="relative mt-1.5"><input id="password" required type="password" minlength="12" maxlength="32" name="password" autocomplete="new-password" class="auth-input w-full rounded-xl border px-3.5 py-2.5 pr-12 text-sm"><button type="button" data-toggle-password="password" class="absolute right-3 top-1/2 -translate-y-1/2 text-stone-500" aria-label="Tampilkan kata sandi"><i data-lucide="eye" class="h-4 w-4"></i></button></div></label>
<div id="password-rules" class="-mt-2 rounded-xl bg-[#FAF8F1] p-3 text-xs dark:bg-[#24211B]"><div class="mb-2 flex items-center justify-between"><p class="auth-muted font-semibold">Ketentuan kata sandi</p><span id="password-strength" class="rounded-full bg-stone-200 px-2 py-1 text-[10px] font-bold text-stone-600 transition-colors dark:bg-stone-700 dark:text-stone-200">Belum diisi</span></div><div class="mb-3 h-1.5 overflow-hidden rounded-full bg-stone-200 dark:bg-stone-700"><div id="password-progress" class="h-full w-0 rounded-full bg-[#E09F09] transition-[width,background-color] duration-300 ease-out"></div></div><ul class="space-y-1.5 auth-muted"><li data-rule="length" class="password-rule">12–32 karakter</li><li data-rule="edges" class="password-rule">Tidak diawali atau diakhiri spasi</li><li data-rule="categories" class="password-rule">Memenuhi minimal 3 kategori karakter</li></ul><p class="auth-muted mt-2">Kategori: huruf besar, huruf kecil, angka, simbol.</p></div>
<label class="auth-label block text-xs font-semibold">Ulangi kata sandi<div class="relative mt-1.5"><input id="password_confirmation" required type="password" name="password_confirmation" autocomplete="new-password" class="auth-input w-full rounded-xl border px-3.5 py-2.5 pr-12 text-sm"><button type="button" data-toggle-password="password_confirmation" class="absolute right-3 top-1/2 -translate-y-1/2 text-stone-500" aria-label="Tampilkan kata sandi"><i data-lucide="eye" class="h-4 w-4"></i></button></div></label>
