<script>(function(){const input=document.getElementById('password'),bar=document.getElementById('password-progress'),badge=document.getElementById('password-strength'),reduced=window.matchMedia('(prefers-reduced-motion: reduce)').matches;const rules={length:v=>v.length>=12&&v.length<=32,edges:v=>v.length>0&&!/^\s|\s$/.test(v),categories:v=>[/[A-Z]/.test(v),/[a-z]/.test(v),/[0-9]/.test(v),/[^A-Za-z0-9 ]/.test(v)].filter(Boolean).length>=3},labels={length:'12–32 karakter',edges:'Tidak diawali atau diakhiri spasi',categories:'Memenuhi minimal 3 kategori karakter'};function update(){const checks=Object.entries(rules).map(([k,fn])=>[k,fn(input.value)]),score=checks.filter(([,ok])=>ok).length;checks.forEach(([k,ok])=>{const el=document.querySelector('[data-rule="'+k+'"]');el.classList.toggle('is-valid',ok);el.classList.toggle('is-invalid',!!input.value&&!ok);el.setAttribute('aria-live','polite');el.innerHTML='<span class="rule-icon" aria-hidden="true">'+(ok?'✓':'○')+'</span><span>'+labels[k]+'</span>'});bar.style.width=(score/3*100)+'%';bar.style.backgroundColor=score===3?'#16803c':score===0?'#E09F09':'#d99b16';badge.textContent=!input.value?'Belum diisi':score===3?'Kuat':score===2?'Hampir kuat':'Perlu dilengkapi';badge.classList.toggle('bg-green-100',score===3);badge.classList.toggle('text-green-800',score===3);document.getElementById('password-rules').classList.toggle('rules-complete',score===3)}input.addEventListener('input',update);document.querySelectorAll('[data-toggle-password]').forEach(b=>b.addEventListener('click',()=>{const el=document.getElementById(b.dataset.togglePassword);el.type=el.type==='password'?'text':'password';b.setAttribute('aria-label',el.type==='password'?'Tampilkan kata sandi':'Sembunyikan kata sandi')}));if(reduced)document.documentElement.classList.add('reduced-motion');update()})();</script>
